def mh(key, n):
    h = 0
    for ch in key:
        h = (h * 31 + ord(ch)) & 0x7fffffff
    return h % n
R = 2
docs = ["hello world hello", "world bigdata", "hello bigdata world", "bigdata hello", "hello world"]
pairs = []
for line in docs:
    for w in line.lower().split():
        pairs.append((w, 1))
buckets = {r: [] for r in range(R)}
for k, v in pairs:
    buckets[mh(k, R)].append((k, v))
final = {}
for r in range(R):
    buckets[r].sort(key=lambda x: x[0])
    agg = {}
    for k, v in buckets[r]:
        agg[k] = agg.get(k, 0) + v
    for k in agg:
        final[k] = final.get(k, 0) + agg[k]
for k in sorted(final):
    print(f"{k}	{final[k]}")
print(f"--reducers={R} total_words={sum(final.values())}")
